def word_frequency(text: str) -> dict[str, int]:
    punct = '!"#$%&\'()*+,-./:;<=>?@[$$^_`{|}~'
    counts = {}
    words = text.split()
    for word in words:
        clean_word = word.lower().strip(punct)
        if clean_word:
            counts[clean_word] = counts.get(clean_word, 0) + 1
    return counts
